export const RELIABILITY_OUTCOMES = Object.freeze(['pass', 'fail', 'missing', 'timeout', 'crash', 'skip', 'reject']);

function isCompleteTrial(trial) {
  return trial && (trial.status === 'pass' || trial.status === 'fail' || trial.status === 'reject');
}

function isSuccess(trial, expected) {
  if (!trial) return false;
  if (expected === 'negative') return trial.status === 'reject' || trial.rejected === true;
  return trial.status === 'pass' || trial.passed === true;
}

function isFailure(trial, expected) {
  if (!trial) return false;
  if (expected === 'negative') return trial.status === 'fail' || trial.passed === true || trial.rejected === false;
  return trial.status === 'fail' || trial.passed === false;
}

function emptyCounts() {
  return { total: 0, complete: 0, incomplete: 0, missing: 0, timeout: 0, crash: 0, skip: 0, passAtK: 0, passK: 0, flake: 0 };
}

/**
 * Aggregate deterministic trial data. The input is intentionally data-only so
 * this module never invokes providers, tests, processes, or the network.
 */
export function aggregateReliability(input = {}) {
  const k = Number.isInteger(input.k) && input.k > 0 ? input.k : 3;
  const minCases = Number.isInteger(input.minCases) && input.minCases >= 0 ? input.minCases : 20;
  const flakeThreshold = Number.isFinite(input.flakeThreshold) ? input.flakeThreshold : 0;
  const cases = Array.isArray(input.cases) ? input.cases : [];
  const counts = emptyCounts();
  counts.total = cases.length;
  const incompleteReasons = { missing: 0, timeout: 0, crash: 0, skip: 0 };
  const anchorViolations = [];

  for (const testCase of cases) {
    const trials = Array.isArray(testCase.trials) ? testCase.trials : [];
    const expected = testCase.expected === 'negative' ? 'negative' : 'positive';
    const statuses = trials.map((trial) => trial?.status ?? 'missing');
    const incomplete = trials.length < k || trials.some((trial) => !isCompleteTrial(trial));
    if (incomplete) {
      counts.incomplete += 1;
      for (const status of statuses) {
        if (status === 'missing' || status === 'timeout' || status === 'crash' || status === 'skip') {
          counts[status] += 1;
          incompleteReasons[status] += 1;
        }
      }
      continue;
    }
    counts.complete += 1;
    const successes = trials.filter((trial) => isSuccess(trial, expected)).length;
    const failures = trials.filter((trial) => isFailure(trial, expected)).length;
    if (successes > 0) counts.passAtK += 1;
    if (successes === k && failures === 0) counts.passK += 1;
    if (isFailure(trials[0], expected) && trials.slice(1).some((trial) => isSuccess(trial, expected))) counts.flake += 1;
    if ((expected === 'positive' && successes !== k) || (expected === 'negative' && successes !== k)) {
      anchorViolations.push({ id: testCase.id, expected, successes, trials: k });
    }
  }

  const denominator = counts.complete;
  const rate = (value) => denominator === 0 ? 0 : value / denominator;
  const flakeRate = rate(counts.flake);
  const anchorGate = anchorViolations.length === 0;
  const reasons = [];
  let gate = 'pass';
  if (counts.complete < minCases) {
    gate = 'insufficient-sample';
    reasons.push(`complete cases ${counts.complete} < required ${minCases}`);
  }
  if (!anchorGate) {
    gate = 'fail';
    reasons.push('anchor violation');
  }
  if (flakeRate > flakeThreshold) {
    gate = 'fail';
    reasons.push(`flake rate ${flakeRate} exceeds threshold ${flakeThreshold}`);
  }

  return {
    k,
    minCases,
    flakeThreshold,
    rawDenominator: counts.total,
    denominator,
    completeCases: counts.complete,
    incompleteCases: counts.incomplete,
    incomplete: {
      count: counts.incomplete,
      missing: counts.missing,
      timeout: counts.timeout,
      crash: counts.crash,
      skip: counts.skip,
      reasons: incompleteReasons,
    },
    passK: { numerator: counts.passK, denominator, rate: rate(counts.passK) },
    passAtK: { numerator: counts.passAtK, denominator, rate: rate(counts.passAtK) },
    flake: { numerator: counts.flake, denominator, rate: flakeRate },
    anchors: { positive: { checked: cases.filter((c) => c.expected !== 'negative').length, violations: anchorViolations.filter((v) => v.expected === 'positive') }, negative: { checked: cases.filter((c) => c.expected === 'negative').length, violations: anchorViolations.filter((v) => v.expected === 'negative') } },
    gate,
    reasons,
  };
}

export const summarizeReliability = aggregateReliability;

export interface ReliabilityTrial {
  status: 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip' | 'reject';
  passed?: boolean;
  rejected?: boolean;
}

export interface ReliabilityCase {
  id: string;
  expected: 'positive' | 'negative';
  trials: ReliabilityTrial[];
}

export interface ReliabilityInput {
  k: number;
  minCases: number;
  flakeThreshold: number;
  cases: ReliabilityCase[];
}

export interface ReliabilityResult {
  k: number;
  minCases: number;
  flakeThreshold: number;
  rawDenominator: number;
  denominator: number;
  completeCases: number;
  incompleteCases: number;
  incomplete: { count: number; missing: number; timeout: number; crash: number; skip: number; reasons: Record<string, number> };
  passK: { numerator: number; denominator: number; rate: number };
  passAtK: { numerator: number; denominator: number; rate: number };
  flake: { numerator: number; denominator: number; rate: number };
  anchors: { positive: { checked: number; violations: unknown[] }; negative: { checked: number; violations: unknown[] } };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
}

export function aggregateReliability(input: ReliabilityInput): ReliabilityResult;

export const summarizeReliability: typeof aggregateReliability;

