const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');
async function read(path) { return await readFile(resolve(ROOT, path), 'utf8'); }
async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full); else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir)); return results;
}
function countMatches(text, pattern) { return [...text.matchAll(pattern)].length; }
function extractScenarioIds(text) { const match = text.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/); return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((m) => m[1]) : []; }
function packageInstalled(name) { const n = name.startsWith('@') ? name.replace('/', '\\') : name; return existsSync(resolve(ROOT, 'node_modules', ...n.split(/[\\/]/))); }
async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file)); let testIdCount = 0, interactiveTagCount = 0, interactiveWithoutInlineTestId = 0;
  for (const file of files) { const text = await readFile(file, 'utf8'); testIdCount += countMatches(text, /data-testid=/g); const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)]; interactiveTagCount += tags.length; interactiveWithoutInlineTestId += tags.filter((m) => !String(m.groups?.attrs ?? '').includes('data-testid')).length; }
  return { fileCount: files.length, testIdCount, interactiveTagCount, interactiveWithoutInlineTestId, inlineSelectorCoverage: interactiveTagCount === 0 ? 1 : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)) };
}
function renderMarkdown(report) {
  const r = report.reliability; const tools = report.externalTools.map((t) => `| ${t.package} | ${t.installed ? 'yes' : 'no'} | ${t.role} |`).join('\n');
  return `# Agent Dev Benefit Evaluation\n\nGenerated: ${report.generatedAt}\n\n## Reliability (deterministic fixture oracle)\n\n- Fixture: ${r.fixtureVersion}; deterministic oracle only; no claim about real providers, humans, or generalization.\n- k=${r.k}; raw denominator=${r.rawDenominator}; complete denominator=${r.denominator}; complete=${r.completeCases}; incomplete=${r.incompleteCases}.\n- pass^k (all k pass): ${r.passK.numerator}/${r.passK.denominator} = ${r.passK.rate.toFixed(3)}.\n- pass@k (at least one pass): ${r.passAtK.numerator}/${r.passAtK.denominator} = ${r.passAtK.rate.toFixed(3)}.\n- flake (first fail, later fixed rerun succeeds): ${r.flake.numerator}/${r.flake.denominator} = ${r.flake.rate.toFixed(3)}; threshold=${r.flakeThreshold}.\n- incomplete: missing=${r.incomplete.missing}, timeout=${r.incomplete.timeout}, crash=${r.incomplete.crash}, skip=${r.incomplete.skip}; excluded from metric denominator and retained here.\n- anchors: positive checked=${r.anchors.positive.checked}, negative checked=${r.anchors.negative.checked}; violations=${r.anchors.positive.violations.length + r.anchors.negative.violations.length}.\n- gate=${r.gate}; reasons=${r.reasons.join('; ') || 'none'}.\n\n## Summary\n\n| Metric | Value |\n| --- | ---: |\n| Dev scenarios | ${report.agentDev.scenarioCount} |\n| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |\n| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |\n| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |\n| Basic a11y rule families | ${report.quality.a11yRuleCount} |\n| Renderer files scanned | ${report.selectorCoverage.fileCount} |\n| data-testid occurrences | ${report.selectorCoverage.testIdCount} |\n| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |\n| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |\n\n## External Tool Readiness\n\n| Package | Installed | Role |\n| --- | --- | --- |\n${tools}\n`;
}
const start = performance.now();
