const scenarioIds = extractScenarioIds(scenarioRegistry); const hostBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? ''; const fixture = JSON.parse(fixtureText); const reliability = aggregateReliability(fixture);
