report.durationMs = Number((performance.now() - start).toFixed(1)); await mkdir(OUT_DIR, { recursive: true }); await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8'); await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8'); console.log(JSON.stringify(report, null, 2));
